  @AnyOf([Language, String])
  @JsonKey(name: 'availableLanguage', includeIfNull: false)
  Object? get availableLanguage;

  /// The identifier for the [[Course]] used by the course [[provider]] (e.g. CS101 or 6.001).
  @StringField(name: 'courseCode')
  String? get courseCode;

  /// Requirements for taking the Course. May be completion of another [[Course]] or a textual description like "permission of instructor". Requirements may be a pre-requisite competency, referenced using [[AlignmentObject]].
  @AnyOf([AlignmentObject, Course, String])
  @JsonKey(name: 'coursePrerequisites', includeIfNull: false)
  Object? get coursePrerequisites;

  /// A description of the qualification, award, certificate, diploma or other educational credential awarded as a consequence of successful completion of this course or program.
  @AnyOf([EducationalOccupationalCredential, String])
  @JsonKey(name: 'educationalCredentialAwarded', includeIfNull: false)
  Object? get educationalCredentialAwarded;

  /// A financial aid type or program which students may use to pay for tuition or fees associated with the program.
  @AnyOf([DefinedTerm, String])
  @JsonKey(name: 'financialAidEligible', includeIfNull: false)
  Object? get financialAidEligible;

  /// An offering of the course at a specific time and place or through specific media or mode of study or to a specific section of students.
  @JsonKey(name: 'hasCourseInstance', includeIfNull: false)
  CourseInstance? get hasCourseInstance;

  /// The number of credits or units awarded by a Course or required to complete an EducationalOccupationalProgram.
  @AnyOf([int, StructuredValue])
  @JsonKey(name: 'numberOfCredits', includeIfNull: false)
  Object? get numberOfCredits;

  /// A description of the qualification, award, certificate, diploma or other occupational credential awarded as a consequence of successful completion of this course or program.
  @AnyOf([EducationalOccupationalCredential, String])
  @JsonKey(name: 'occupationalCredentialAwarded', includeIfNull: false)
  Object? get occupationalCredentialAwarded;

  /// Indicates (typically several) Syllabus entities that lay out what each section of the overall course will cover.
  @JsonKey(name: 'syllabusSections', includeIfNull: false)
  Syllabus? get syllabusSections;

  /// The total number of students that have enrolled in the history of the course.
  @IntegerField(name: 'totalHistoricalEnrollment')
  int? get totalHistoricalEnrollment;

}

/// An instance of a [[Course]] which is distinct from other instances because it is offered at a different time or location or through different media or modes of study or to a specific section of students.
