  ///
  @AnyOf([Demand, Offer])
  @JsonKey(name: 'offers', includeIfNull: false)
  Object? get offers;

  /// An organizer of an Event.
  @AnyOf([Organization, Person])
  @JsonKey(name: 'organizer', includeIfNull: false)
  Object? get organizer;

  /// A performer at the event&#x2014;for example, a presenter, musician, musical group or actor.
  @AnyOf([Organization, Person])
  @JsonKey(name: 'performer', includeIfNull: false)
  Object? get performer;

  /// The main performer or performers of the event&#x2014;for example, a presenter, musician, or actor.
  @AnyOf([Organization, Person])
  @JsonKey(name: 'performers', includeIfNull: false)
  Object? get performers;

  /// Used in conjunction with eventStatus for rescheduled or cancelled events. This property contains the previously scheduled start date. For rescheduled events, the startDate property should be used for the newly scheduled start date. In the (rare) case of an event that has been postponed and rescheduled multiple times, this field may be repeated.
  @StringField(name: 'previousStartDate', format: 'date-time')
  String? get previousStartDate;

  /// The CreativeWork that captured all or part of this Event.
  @JsonKey(name: 'recordedIn', includeIfNull: false)
