  @JsonKey(name: '@context', includeIfNull: false)
  String? get context;

  @override
  @JsonKey(name: '@type', includeIfNull: false)
  String? get type;

  /// Physical address of the item.
  @AnyOf([PostalAddress, String])
  @JsonKey(name: 'address', includeIfNull: false)
  Object? get address;

  /// The country. Recommended to be in 2-letter [ISO 3166-1 alpha-2](http://en.wikipedia.org/wiki/ISO_3166-1) format, for example "US". For backward compatibility, a 3-letter [ISO 3166-1 alpha-3](https://en.wikipedia.org/wiki/ISO_3166-1_alpha-3) country code such as "SGP" or a full country name such as "Singapore" can also be used.
  @AnyOf([Country, String])
  @JsonKey(name: 'addressCountry', includeIfNull: false)
  Object? get addressCountry;

  /// The elevation of a location ([WGS 84](https://en.wikipedia.org/wiki/World_Geodetic_System)). Values may be of the form 'NUMBER UNIT\_OF\_MEASUREMENT' (e.g., '1,000 m', '3,200 ft') while numbers alone should be assumed to be a value in meters.
  @AnyOf([double, String])
  @JsonKey(name: 'elevation', includeIfNull: false)
  Object? get elevation;

  /// The latitude of a location. For example ```37.42242``` ([WGS 84](https://en.wikipedia.org/wiki/World_Geodetic_System)).
  @AnyOf([double, String])
  @JsonKey(name: 'latitude', includeIfNull: false)
  Object? get latitude;

  /// The longitude of a location. For example ```-122.08585``` ([WGS 84](https://en.wikipedia.org/wiki/World_Geodetic_System)).
  @AnyOf([double, String])
  @JsonKey(name: 'longitude', includeIfNull: false)
  Object? get longitude;

  /// The postal code. For example, 94043.
  @StringField(name: 'postalCode')
  String? get postalCode;

}

/// The geographic shape of a place. A GeoShape can be described using several properties whose values are based on latitude/longitude pairs. Either whitespace or commas can be used to separate latitude and longitude; whitespace should be used when writing a list of several such points.
@Schema(description: 'The geographic shape of a place. A GeoShape can be described using several properties whose values are based on latitude/longitude pairs. Either whitespace or commas can be used to separate latitude and longitude; whitespace should be used when writing a list of several such points.')
abstract class GeoShape implements StructuredValue, $Thing {
  @override
  @JsonKey(name: '@context', includeIfNull: false)
  String? get context;

  @override
  @JsonKey(name: '@type', includeIfNull: false)
  String? get type;

  /// Physical address of the item.
  @AnyOf([PostalAddress, String])
  @JsonKey(name: 'address', includeIfNull: false)
  Object? get address;

  /// The country. Recommended to be in 2-letter [ISO 3166-1 alpha-2](http://en.wikipedia.org/wiki/ISO_3166-1) format, for example "US". For backward compatibility, a 3-letter [ISO 3166-1 alpha-3](https://en.wikipedia.org/wiki/ISO_3166-1_alpha-3) country code such as "SGP" or a full country name such as "Singapore" can also be used.
  @AnyOf([Country, String])
  @JsonKey(name: 'addressCountry', includeIfNull: false)
  Object? get addressCountry;

  /// A box is the area enclosed by the rectangle formed by two points. The first point is the lower corner, the second point is the upper corner. A box is expressed as two points separated by a space character.
  @StringField(name: 'box')
  String? get box;

  /// A circle is the circular region of a specified radius centered at a specified latitude and longitude. A circle is expressed as a pair followed by a radius in meters.
  @StringField(name: 'circle')
  String? get circle;

  /// The elevation of a location ([WGS 84](https://en.wikipedia.org/wiki/World_Geodetic_System)). Values may be of the form 'NUMBER UNIT\_OF\_MEASUREMENT' (e.g., '1,000 m', '3,200 ft') while numbers alone should be assumed to be a value in meters.
  @AnyOf([double, String])
  @JsonKey(name: 'elevation', includeIfNull: false)
  Object? get elevation;

  /// A line is a point-to-point path consisting of two or more points. A line is expressed as a series of two or more point objects separated by space.
  @StringField(name: 'line')
  String? get line;

  /// A polygon is the area enclosed by a point-to-point path for which the starting and ending points are the same. A polygon is expressed as a series of four or more space delimited points where the first and final points are identical.
  @StringField(name: 'polygon')
  String? get polygon;

  /// The postal code. For example, 94043.
  @StringField(name: 'postalCode')
  String? get postalCode;

}

/// (Eventually to be defined as) a supertype of GeoShape designed to accommodate definitions from Geo-Spatial best practices.
@Schema(description: '(Eventually to be defined as) a supertype of GeoShape designed to accommodate definitions from Geo-Spatial best practices.')
abstract class GeospatialGeometry implements Intangible, $Thing {
  @override
  @JsonKey(name: '@context', includeIfNull: false)
  String? get context;

  @override
  @JsonKey(name: '@type', includeIfNull: false)
  String? get type;

  /// Represents a relationship between two geometries (or the places they represent), relating a containing geometry to a contained geometry. "a contains b iff no points of b lie in the exterior of a, and at least one point of the interior of b lies in the interior of a". As defined in [DE-9IM](https://en.wikipedia.org/wiki/DE-9IM).
  @AnyOf([GeospatialGeometry, Place])
  @JsonKey(name: 'geoContains', includeIfNull: false)
  Object? get geoContains;

  /// Represents a relationship between two geometries (or the places they represent), relating a geometry to another that covers it. As defined in [DE-9IM](https://en.wikipedia.org/wiki/DE-9IM).
  @AnyOf([GeospatialGeometry, Place])
  @JsonKey(name: 'geoCoveredBy', includeIfNull: false)
  Object? get geoCoveredBy;

  /// Represents a relationship between two geometries (or the places they represent), relating a covering geometry to a covered geometry. "Every point of b is a point of (the interior or boundary of) a". As defined in [DE-9IM](https://en.wikipedia.org/wiki/DE-9IM).
  @AnyOf([GeospatialGeometry, Place])
  @JsonKey(name: 'geoCovers', includeIfNull: false)
  Object? get geoCovers;

  /// Represents a relationship between two geometries (or the places they represent), relating a geometry to another that crosses it: "a crosses b: they have some but not all interior points in common, and the dimension of the intersection is less than that of at least one of them". As defined in [DE-9IM](https://en.wikipedia.org/wiki/DE-9IM).
  @AnyOf([GeospatialGeometry, Place])
  @JsonKey(name: 'geoCrosses', includeIfNull: false)
  Object? get geoCrosses;

  /// Represents spatial relations in which two geometries (or the places they represent) are topologically disjoint: "they have no point in common. They form a set of disconnected geometries." (A symmetric relationship, as defined in [DE-9IM](https://en.wikipedia.org/wiki/DE-9IM).)
  @AnyOf([GeospatialGeometry, Place])
  @JsonKey(name: 'geoDisjoint', includeIfNull: false)
  Object? get geoDisjoint;

  /// Represents spatial relations in which two geometries (or the places they represent) are topologically equal, as defined in [DE-9IM](https://en.wikipedia.org/wiki/DE-9IM). "Two geometries are topologically equal if their interiors intersect and no part of the interior or boundary of one geometry intersects the exterior of the other" (a symmetric relationship).
  @AnyOf([GeospatialGeometry, Place])
  @JsonKey(name: 'geoEquals', includeIfNull: false)
  Object? get geoEquals;

  /// Represents spatial relations in which two geometries (or the places they represent) have at least one point in common. As defined in [DE-9IM](https://en.wikipedia.org/wiki/DE-9IM).
  @AnyOf([GeospatialGeometry, Place])
  @JsonKey(name: 'geoIntersects', includeIfNull: false)
  Object? get geoIntersects;

  /// Represents a relationship between two geometries (or the places they represent), relating a geometry to another that geospatially overlaps it, i.e. they have some but not all points in common. As defined in [DE-9IM](https://en.wikipedia.org/wiki/DE-9IM).
  @AnyOf([GeospatialGeometry, Place])
  @JsonKey(name: 'geoOverlaps', includeIfNull: false)
  Object? get geoOverlaps;

  /// Represents spatial relations in which two geometries (or the places they represent) touch: "they have at least one boundary point in common, but no interior points." (A symmetric relationship, as defined in [DE-9IM](https://en.wikipedia.org/wiki/DE-9IM).)
  @AnyOf([GeospatialGeometry, Place])
  @JsonKey(name: 'geoTouches', includeIfNull: false)
  Object? get geoTouches;

  /// Represents a relationship between two geometries (or the places they represent), relating a geometry to one that contains it, i.e. it is inside (i.e. within) its interior. As defined in [DE-9IM](https://en.wikipedia.org/wiki/DE-9IM).
  @AnyOf([GeospatialGeometry, Place])
  @JsonKey(name: 'geoWithin', includeIfNull: false)
  Object? get geoWithin;

}

