/// Instructions that explain how to achieve a result by performing a sequence of steps.
@Schema(description: 'Instructions that explain how to achieve a result by performing a sequence of steps.')
abstract class HowTo implements CreativeWork, $Thing {
  @override
  @JsonKey(name: '@context', includeIfNull: false)
  String? get context;

  @override
  @JsonKey(name: '@type', includeIfNull: false)
  String? get type;

  /// The estimated cost of the supply or supplies consumed when performing instructions.
  @AnyOf([MonetaryAmount, String])
  @JsonKey(name: 'estimatedCost', includeIfNull: false)
  Object? get estimatedCost;

  /// The length of time it takes to perform instructions or a direction (not including time to prepare the supplies), in [ISO 8601 duration format](http://en.wikipedia.org/wiki/ISO_8601).
  @JsonKey(name: 'performTime', includeIfNull: false)
  Duration? get performTime;

  /// The length of time it takes to prepare the items to be used in instructions or a direction, in [ISO 8601 duration format](http://en.wikipedia.org/wiki/ISO_8601).
  @JsonKey(name: 'prepTime', includeIfNull: false)
  Duration? get prepTime;

  /// A single step item (as HowToStep, text, document, video, etc.) or a HowToSection.
  @AnyOf([CreativeWork, HowToSection, HowToStep, String])
  @JsonKey(name: 'step', includeIfNull: false)
  Object? get step;

  /// A single step item (as HowToStep, text, document, video, etc.) or a HowToSection (originally misnamed 'steps'; 'step' is preferred).
  @AnyOf([CreativeWork, ItemList, String])
  @JsonKey(name: 'steps', includeIfNull: false)
  Object? get steps;

  /// A sub-property of instrument. A supply consumed when performing instructions or a direction.
  @AnyOf([HowToSupply, String])
  @JsonKey(name: 'supply', includeIfNull: false)
  Object? get supply;

  /// A sub property of instrument. An object used (but not consumed) when performing instructions or a direction.
  @AnyOf([HowToTool, String])
  @JsonKey(name: 'tool', includeIfNull: false)
  Object? get tool;

  /// The total time required to perform instructions or a direction (including time to prepare the supplies), in [ISO 8601 duration format](http://en.wikipedia.org/wiki/ISO_8601).
  @JsonKey(name: 'totalTime', includeIfNull: false)
  Duration? get totalTime;

  /// The quantity that results by performing instructions. For example, a paper airplane, 10 personalized candles.
  @AnyOf([QuantitativeValue, String])
  @JsonKey(name: 'yield', includeIfNull: false)
  Object? get yield;

}

