  @AnyOf([DefinedTerm, String])
  @JsonKey(name: 'keywords', includeIfNull: false)
  Object? get keywords;

  /// An associated logo.
  @AnyOf([ImageObject, String])
  @JsonKey(name: 'logo', includeIfNull: false)
  Object? get logo;

  /// The manufacturer of the product.
  @JsonKey(name: 'manufacturer', includeIfNull: false)
  Organization? get manufacturer;

  /// A material that something is made from, e.g. leather, wool, cotton, paper.
  @AnyOf([Product, String])
  @JsonKey(name: 'material', includeIfNull: false)
  Object? get material;

