  @AnyOf([double, QuantitativeValue])
  @JsonKey(name: 'numberOfAxles', includeIfNull: false)
  Object? get numberOfAxles;

  /// The number of doors.\n\nTypical unit code(s): C62.
  @AnyOf([double, QuantitativeValue])
  @JsonKey(name: 'numberOfDoors', includeIfNull: false)
  Object? get numberOfDoors;

